import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"自研或采购监控能力","description":"","frontmatter":{"title":"自研或采购监控能力","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/quality/observability.md","filePath":"frontend/decisions/quality/observability.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/quality/observability.md"};function l(o,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="自研或采购监控能力" tabindex="-1">自研或采购监控能力 <a class="header-anchor" href="#自研或采购监控能力" aria-label="Permalink to &quot;自研或采购监控能力&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>前端监控包含浏览器采集 SDK、Source Map 处理、事件接收、存储查询、聚合告警和治理界面。所谓自研或采购，通常不是整套二选一：团队可以自定义业务埋点和数据清洗，同时购买错误聚合与存储；也可以使用开源后端并保留自有采集入口。</p><p>监控模型和指标设计参见<a href="/frontend/guide/engineering/reliability/observability">前端可观测性模型</a>与<a href="/frontend/guide/engineering/reliability/error-monitoring">错误、日志与追踪</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>成熟 SaaS 能快速提供错误聚合、性能和告警，但成本、数据流向和锁定需要管理。自研可以控制采集与数据驻留，却要承担海量事件、符号化、查询、保留和 24 小时可靠性。</p><p>决策应先分解能力清单，再决定每层责任，避免比较两个模糊的“整套方案”。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-数据与安全硬约束" tabindex="-1">2.1 数据与安全硬约束 <a class="header-anchor" href="#_2-1-数据与安全硬约束" aria-label="Permalink to &quot;2.1 数据与安全硬约束&quot;">​</a></h3><ul><li>禁止采集密码、令牌、完整表单、未脱敏 URL 和用户私密内容；</li><li>数据驻留、保留、删除和用户同意符合隐私与合同；</li><li>Source Map 受访问控制，不能公开部署源代码；</li><li>采集失败或 SDK 异常不能阻塞业务主线程和页面加载；</li><li>供应商和自托管依赖都通过安全与供应链审查。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较能力覆盖、接入速度、事件量与成本、数据控制、查询和告警、采样、Source Map、跨端追踪、可用性、运维人力、支持、导出和退出成本。</p><h2 id="_3-候选责任模型" tabindex="-1">3. 候选责任模型 <a class="header-anchor" href="#_3-候选责任模型" aria-label="Permalink to &quot;3. 候选责任模型&quot;">​</a></h2><h3 id="_3-1-完全自研" tabindex="-1">3.1 完全自研 <a class="header-anchor" href="#_3-1-完全自研" aria-label="Permalink to &quot;3.1 完全自研&quot;">​</a></h3><p>自建 SDK、接收、处理、存储、查询和告警。适合监控本身是平台产品、存在无法由外部满足的硬约束，且组织已经具备数据与值班团队。最容易低估的是存储规模、聚合质量和持续兼容。</p><h3 id="_3-2-开源自托管" tabindex="-1">3.2 开源自托管 <a class="header-anchor" href="#_3-2-开源自托管" aria-label="Permalink to &quot;3.2 开源自托管&quot;">​</a></h3><p>使用开源采集或后端部署到自有基础设施，增强数据控制并减少从零研发。团队仍负责升级、容量、备份、安全和故障恢复；许可证和社区维护也要评估。</p><h3 id="_3-3-商业-saas" tabindex="-1">3.3 商业 SaaS <a class="header-anchor" href="#_3-3-商业-saas" aria-label="Permalink to &quot;3.3 商业 SaaS&quot;">​</a></h3><p>购买错误、性能、会话或追踪能力，以订阅换取成熟产品和服务支持。适合需要快速达到生产可用且运维容量有限的团队，前提是数据和合同硬约束通过。</p><h3 id="_3-4-混合方案" tabindex="-1">3.4 混合方案 <a class="header-anchor" href="#_3-4-混合方案" aria-label="Permalink to &quot;3.4 混合方案&quot;">​</a></h3><p>自有轻量采集网关负责脱敏、租户和路由，后端错误聚合与存储使用 SaaS 或托管开源；业务指标进入公司数据平台。这能控制敏感边界，但增加数据管道和双端排障。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是 5 个 B2B Web 产品、日活 20 万、两名可靠性工程师。公司允许合规区域 SaaS，但禁止传输客户输入、令牌和完整 URL；要求 30 天错误保留和 7 天原始事件，需与工单系统集成。</p><table tabindex="0"><thead><tr><th>维度</th><th>完全自研</th><th>开源自托管</th><th>商业 SaaS</th><th>网关 + SaaS</th></tr></thead><tbody><tr><td>上线时间</td><td>6 至 12 个月</td><td>2 至 4 个月</td><td>2 至 4 周</td><td>4 至 8 周</td></tr><tr><td>数据控制</td><td>最高</td><td>高</td><td>依合同和配置</td><td>高，先脱敏</td></tr><tr><td>运维人力</td><td>很高</td><td>高</td><td>低</td><td>中</td></tr><tr><td>错误聚合与 Source Map</td><td>全部自建</td><td>现成但自维</td><td>成熟</td><td>SaaS 提供</td></tr><tr><td>业务字段治理</td><td>自建</td><td>自建</td><td>配置为主</td><td>网关统一</td></tr><tr><td>退出成本</td><td>内部系统</td><td>数据和部署迁移</td><td>厂商查询与历史数据</td><td>事件 Schema 可控</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>推荐“自有采集策略与轻量网关 + 商业 SaaS 后端”：浏览器 SDK 只产生经过白名单的错误、性能和版本字段；网关再次脱敏、采样并附加租户分类，随后发送到满足区域和删除条款的 SaaS。业务转化指标进入现有数据平台，不放入错误监控产品。</p><p>不自研错误聚合、Source Map 符号化、查询和告警，因为当前两人团队无法覆盖长期可用性，且这些能力不是产品差异化。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>团队可以在两个月内获得成熟排障能力，并保留采集和隐私控制。代价是订阅费用、供应商查询语法和网关维护；网关故障必须丢弃监控而不是阻塞业务。</p><p>需要设置事件预算、动态采样、项目配额和成本告警。高流量低价值错误不能无限采集。Source Map 与发布版本绑定上传，并设置访问和删除流程。</p><p>退出路径包括稳定的内部事件 Schema、原始事件短期归档和定期导出演练。聚合分组和历史查询通常无法完全无损迁移，应把它计入接受后果。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>强数据驻留且供应商无法满足时，SaaS 应被硬性淘汰。</li><li>不要因为已有日志系统就低估浏览器错误上下文和 Source Map 能力。</li><li>自托管开源不是“无采购成本”，仍需容量和值班。</li><li>会话回放可能采集敏感内容，未完成隐私评估前不应开启。</li><li>不要让监控 SDK 同步阻塞首屏或抛出影响业务的异常。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>五个 Web 产品如何获得错误与性能监控</td></tr><tr><td>硬约束</td><td>区域驻留；字段白名单；30 天聚合；监控失败不影响业务</td></tr><tr><td>候选</td><td>完全自研、开源自托管、SaaS、网关 + SaaS</td></tr><tr><td>决定</td><td>自有采集治理和网关，采购 SaaS 聚合存储</td></tr><tr><td>证据</td><td>事件量试算、两周接入原型、隐私评审、运维容量和三年 TCO</td></tr><tr><td>接受代价</td><td>订阅、供应商查询锁定、轻量网关值班</td></tr><tr><td>明确不做</td><td>会话回放、客户输入采集、自研查询后端</td></tr><tr><td>验证指标</td><td>SDK 开销、事件丢弃、聚合有效率、告警噪声、月成本、MTTR</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>年度成本增长超过 30%、供应商无法满足删除或驻留、告警和聚合质量连续不达标、数据规模使自托管 TCO 更低，或公司已有可复用统一平台时复查。合同续签前至少六个月执行一次导出和替代方案演练。</p>',37)])])}const p=a(i,[["render",l]]);export{u as __pageData,p as default};
